<script setup>
import {ref,computed,watch,onMounted,onUnmounted,nextTick} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {useDungeon} from '../stores/dungeon'
import {dungeonLevels,dungeonHeroes} from '../data/dungeon-levels'
import {targets} from '../lib/dungeonWorld'
import DungeonWorld from '../components/dungeon/DungeonWorld.vue'
import GameItemShop from '../components/GameItemShop.vue'
import {useArcade} from '../stores/arcade'
import DungeonHero from '../components/dungeon/DungeonHero.vue'
const d=useDungeon(),help=ref(null),npcDialog=ref(null),codeDialog=ref(null),exitDialog=ref(null),book=ref(null),modal=ref(false),npc=ref(0),current=ref(null),draft=ref(''),feedback=ref(null),formError=ref(''),questionKey=ref(''),requestDraft=ref(''),localItems=ref([]),roundStart=ref(0),roundHost=ref(null),roundCount=ref(3),position=ref({x:4,y:22}),onlyWrong=ref(false),bookTab=ref('concepts');let observer,leaveResolve=null,leavePromise=null,firstTutorial=true,alive=true
const level=computed(()=>dungeonLevels[(d.session?.level??1)-1]),hero=computed(()=>dungeonHeroes.find(h=>h.id===d.hero)),rounds=computed(()=>dungeonLevels.slice(roundStart.value,roundStart.value+roundCount.value)),nextTarget=computed(()=>d.session?.level===5?[24,12]:targets[Math.min(d.session?.solved??0,3)]),direction=computed(()=>{const [x,y]=nextTarget.value,dx=x-position.value.x,dy=y-position.value.y;return (dy<0?'↑':dy>0?'↓':'')+(dx<0?'←':dx>0?'→':'')||'도착'}),attempts=computed(()=>d.archive.attempts.filter(a=>!onlyWrong.value||!a.correct))
const notes=[['print()로 값을 화면에 표시합니다. 숫자끼리 +는 덧셈, 문자열끼리 +는 이어 붙이기입니다.','변수에 값을 저장하며 int는 정수, float는 실수, str은 문자열, bool은 참·거짓입니다.','따옴표와 괄호는 쌍을 맞춥니다. 계산은 *, /, //, % 등 연산자로 표현합니다.','함수의 매개변수는 호출마다 바뀝니다. 계산한 값은 return으로 돌려줍니다.'],['비교 연산은 True 또는 False를 만듭니다. and는 모두 참, or는 하나라도 참이면 참입니다.','if → elif → else 순서로 처음 참인 분기만 실행합니다. 들여쓰기와 :가 중요합니다.','>=는 기준과 같은 값도 포함합니다. 경계값 바로 아래·같은 값·바로 위를 확인하세요.','모든 분기가 의도한 값을 return하는지 확인하세요. 아무것도 반환하지 않으면 None입니다.'],['range(start, stop, step)은 stop을 포함하지 않습니다. for는 차례대로 값을 꺼냅니다.','break는 반복 종료, continue는 현재 반복을 건너뜁니다. 둘의 위치에 따라 결과가 달라집니다.','while은 조건이 참인 동안 반복합니다. 조건에 쓰인 값을 갱신해야 무한 반복을 막습니다.','누적 변수는 반복 전에 초기화합니다. +=는 이전 결과에 값을 더합니다.'],['리스트는 순서가 있으며 인덱스는 0부터 시작합니다. 빈 리스트도 고려하세요.','매개변수는 함수가 입력받는 이름이고 return은 결과를 전달하는 키워드입니다.','리스트에 하나를 추가하려면 append, 문자열을 대문자로 바꾸려면 upper를 사용합니다.','여러 매개변수와 반복·조건을 조합해 함수를 만듭니다. 다른 입력에서도 동작해야 합니다.'],['함수의 인수부터 계산하고 반환값을 바깥 식에 대입해 실행을 따라가세요.','누적 값에 =를 쓰면 이전 값이 사라집니다. +=와 비교해 보세요.','반복 범위와 조건을 분리해 추적한 뒤 선택된 값만 누적하세요.','빈 리스트·경계값·중복 원소를 테스트하면 조건과 반환 오류를 찾기 쉽습니다.']]
function moveRound(n){roundStart.value=Math.max(0,Math.min(5-roundCount.value,roundStart.value+n))}
function show(dialog){modal.value=true;dialog.showModal()}
function close(dialog){dialog.close();modal.value=false}
async function startLevel(n){await d.enter(n);if(d.screen==='play'){localItems.value=[];position.value={x:4,y:22};if(firstTutorial){firstTutorial=false;await nextTick();show(help.value)}}}
function interact(event){if(event.kind==='empty'){formError.value='다음 목표 '+direction.value+' 쪽으로 이동해 NPC 가까이에서 E를 눌러 보세요.';return}if(event.kind==='exit'){if(d.session.solved<4){formError.value='필수 미션 4개를 먼저 해결해야 출구가 열려요.';return}d.screen=d.session.done?'ending':'rounds';return}if(event.index>d.session.solved){formError.value='앞의 NPC 미션부터 순서대로 해결해 주세요.';return}npc.value=event.index;formError.value='';show(npcDialog.value)}
function openQuestion(){if(npc.value!==d.session.solved||!d.session.question)return;close(npcDialog.value);current.value={...d.session.question};draft.value=['fix','code'].includes(current.value.type)?current.value.code:'';feedback.value=null;formError.value='';questionKey.value=crypto.randomUUID();requestDraft.value=draft.value;show(codeDialog.value)}
async function submit(){if(d.busy||feedback.value?.correct||!draft.value.trim())return;if(requestDraft.value!==draft.value){questionKey.value=crypto.randomUUID();requestDraft.value=draft.value}try{feedback.value=await d.answer(current.value.id,draft.value,questionKey.value);questionKey.value=crypto.randomUUID();formError.value=''}catch(e){formError.value=e.message}}
async function useGameItem(result){if(result.item==='dungeon-hint'){feedback.value={correct:false,hint:result.hint};return}d.session=result.session;feedback.value=result;await useArcade().refresh();await d.loadHistory()}
function retry(){feedback.value=null;questionKey.value=crypto.randomUUID();formError.value=''}
function advance(){const result=feedback.value;close(codeDialog.value);feedback.value=null;if(result?.levelCleared)d.screen=d.session.done?'ending':'rounds'}
function tab(e){const el=e.target,start=el.selectionStart,end=el.selectionEnd;draft.value=draft.value.slice(0,start)+'    '+draft.value.slice(end);nextTick(()=>{el.selectionStart=el.selectionEnd=start+4})}
async function openBook(){try{await d.loadHistory();show(book.value)}catch(e){formError.value=e.message}}
function askExit(){if(!d.session)return Promise.resolve(true);if(leavePromise)return leavePromise;show(exitDialog.value);leavePromise=new Promise(resolve=>leaveResolve=resolve);return leavePromise}
async function confirmExit(){await d.end();close(exitDialog.value);const done=leaveResolve;leaveResolve=null;leavePromise=null;done?.(true)}
function cancelExit(){close(exitDialog.value);const done=leaveResolve;leaveResolve=null;leavePromise=null;done?.(false)}
function unload(e){if(d.session){e.preventDefault();e.returnValue=''}}function pagehide(){d.dispose()}
function pageshow(event){if(event.persisted)d.initialize()}
function visibility(){if(document.hidden&&d.session&&!d.session.paused&&!d.busy)d.pause(true)}
onBeforeRouteLeave(async()=>await askExit())
watch(()=>d.session?.id,id=>{if(id){roundStart.value=0;localItems.value=[];position.value={x:4,y:22};firstTutorial=true}})
watch(()=>d.session?.cleared.length,n=>{if(n)roundStart.value=Math.min(5-roundCount.value,Math.floor(n/roundCount.value)*roundCount.value)})
onMounted(async()=>{await d.initialize();if(!alive)return;observer=new ResizeObserver(entries=>{const width=entries[0]?.contentRect.width??1000;roundCount.value=width<520?1:width<850?2:3;roundStart.value=Math.min(roundStart.value,5-roundCount.value)});if(roundHost.value)observer.observe(roundHost.value);window.addEventListener('beforeunload',unload);window.addEventListener('pagehide',pagehide);window.addEventListener('pageshow',pageshow);document.addEventListener('visibilitychange',visibility)})
watch(roundHost,(value,old)=>{if(old)observer?.unobserve(old);if(value)observer?.observe(value)})
onUnmounted(()=>{alive=false;observer?.disconnect();window.removeEventListener('beforeunload',unload);window.removeEventListener('pagehide',pagehide);window.removeEventListener('pageshow',pageshow);document.removeEventListener('visibilitychange',visibility);for(const dialog of [help,npcDialog,codeDialog,exitDialog,book])dialog.value?.close();leaveResolve?.(true);d.dispose()})
</script>
<template><div class="dungeon-root"><header class="dungeon-heading"><div><p>PYTHON / CODING ADVENTURE</p><h1>Python 코딩 던전 탈출</h1></div><div class="dungeon-toolbar"><span class="dungeon-reward">최대 200P</span><button @click="openBook">코딩 도감·오답노트</button><button v-if="d.session" @click="askExit">게임 종료</button></div></header><p v-if="d.error||formError&&!modal" class="dungeon-notice" role="alert">{{d.error||formError}}</p>
<section v-if="d.screen==='title'" class="dungeon-title"><div class="title-art"><img src="/images/dungeon/title.svg" alt="별빛 문과 숲으로 둘러싸인 독창적인 픽셀 던전"/><div class="title-lettering"><p>THE LOST PYTHON CODEX</p><h2>코딩 던전<br/>탈출</h2><span>작은 코드가 여는 다섯 개의 문</span></div></div><div class="title-menu"><p>5 LEVEL · 입문부터 함수까지 · 최초 클리어 총 200P</p><button class="dungeon-primary" :disabled="!d.ready||d.busy" @click="d.choose">{{!d.ready?'모험 준비 중…':'GAME START'}}</button><button @click="show(help)">게임 방법</button><button v-if="!d.ready&&d.error" @click="d.initialize">다시 연결</button><small>방향키 / WASD 이동 · E 상호작용 · 모바일 방향 패드 지원</small><small v-if="d.archive.total">이전 최초 보상 {{d.archive.total}} / 200P 수령 · 재도전 보상은 중복 지급되지 않아요.</small></div></section>
<section v-else-if="d.screen==='heroes'" class="dungeon-panel hero-select"><p>CHOOSE YOUR ADVENTURER</p><h2>함께 모험할 탐험가를 고르세요</h2><div class="dungeon-heroes"><button v-for="h in dungeonHeroes" :key="h.id" :class="{selected:d.hero===h.id}" :aria-pressed="d.hero===h.id" :disabled="d.busy" @click="d.hero=h.id"><DungeonHero :hero="h.id"/><strong>{{h.name}}</strong><small>{{h.description}}</small></button></div><div class="dungeon-toolbar"><button :disabled="d.busy" @click="d.screen='title'">뒤로</button><button class="dungeon-primary" :disabled="d.busy" @click="d.start">{{d.busy?'새 문제 검증 중…':'이 탐험가로 시작'}}</button></div></section>
<section v-else-if="d.screen==='story'" class="dungeon-panel dungeon-story"><DungeonHero :hero="d.hero"/><p>PROLOGUE / 사라진 파이썬의 서</p><h2>다섯 개의 봉인을 풀어 주세요.</h2><p>코드 골렘이 파이썬의 서를 조각내고 다섯 지역의 문을 잠갔습니다.<br/>{{hero.name}}는 NPC에게 개념을 배우고, 오류 난 주문을 고쳐 출구를 열어야 합니다.</p><ol><li>방향키 또는 WASD로 이동합니다. 모바일은 화면의 방향 패드를 사용해요.</li><li>금색 테두리 NPC 가까이에서 E를 누르면 대화하고 문제를 풀 수 있어요.</li><li>지역마다 필수 미션 4개! 틀리면 힌트를 읽고 다시 도전하세요.</li></ol><p>게임을 나가면 진행은 초기화되지만 포인트·학습 기록은 남습니다.</p><button class="dungeon-primary" :disabled="d.busy" @click="startLevel(1)">LEVEL 1 입장 →</button></section>
<section v-else-if="d.screen==='rounds'" class="dungeon-panel adventure-map"><p>ADVENTURE MAP</p><h2>다음 모험으로 출발할까요?</h2><p>출력의 마을에서 최종 보스까지 · 현재 플레이 {{d.session.cleared.length}} / 5 클리어</p><div class="round-carousel" ref="roundHost"><button aria-label="이전 라운드 카드" :disabled="roundStart===0" @click="moveRound(-1)">〈</button><div class="round-cards" :style="{'--round-count':roundCount}"><button v-for="r in rounds" :key="r.id" :class="['round-card',{locked:r.id>d.session.unlocked,cleared:d.session.cleared.includes(r.id)}]" :aria-label="'LEVEL '+r.id+' '+r.name+(r.id>d.session.unlocked?' 잠김':'')" :disabled="d.busy" @click="startLevel(r.id)"><span>{{r.id>d.session.unlocked?'🔒':d.session.cleared.includes(r.id)?'✓':'✦'}}</span><small>LEVEL {{r.id}}</small><strong>{{r.name}}</strong><b>{{r.reward}}P</b><small>{{r.id>d.session.unlocked?'이전 라운드 클리어 필요':d.session.cleared.includes(r.id)?'클리어 완료':'도전하기 →'}}</small></button></div><button aria-label="다음 라운드 카드" :disabled="roundStart>=5-roundCount" @click="moveRound(1)">〉</button></div><p>잠금은 이번 모험 기준입니다. 보상은 사용자별·라운드별 최초 한 번만 지급돼요.</p><button @click="openBook">지금까지 모은 개념 보기</button></section>
<section v-else-if="d.screen==='play'" class="dungeon-play"><div class="dungeon-hud"><strong>LEVEL {{d.session.level}} · {{level.name}}</strong><span>필수 미션 {{d.session.solved}} / 4</span><progress :value="d.session.solved" max="4" aria-label="라운드 진행률"/><b>이번 모험 +{{d.session.earned}}P · 누적 {{d.archive.total}}/200P</b><button :disabled="d.busy" @click="d.pause(!d.session.paused)">{{d.session.paused?'▶ 계속하기':'Ⅱ 일시정지'}}</button><button @click="d.screen='rounds'">모험 지도</button></div><div v-if="d.session.level===5" class="boss-health"><b>코드 골렘 HP {{d.session.bossHp}} / 100</b><progress :value="d.session.bossHp" max="100" aria-label="보스 HP"/></div><div class="dungeon-play-grid"><div class="dungeon-map-frame"><DungeonWorld :level="d.session.level" :hero="d.hero" :solved="d.session.solved" :active="!d.session.paused&&!d.busy&&!modal" @interact="interact" @position="position=$event" @collect="item=>{if(!localItems.includes(item))localItems.push(item)}"/><div v-if="d.session.paused" class="dungeon-paused"><h2>PAUSED</h2><p>잠시 쉬어 가도 괜찮아요.</p><button :disabled="d.busy" @click="d.pause(false)">계속하기</button></div></div><aside class="dungeon-missions"><p>CURRENT QUEST</p><h2>{{d.session.solved<4?level.concepts[d.session.solved]:'출구가 열렸어요!'}}</h2><p>다음 목표 {{direction}} · 좌표 {{nextTarget[0]}}, {{nextTarget[1]}}</p><p>{{notes[d.session.level-1][Math.min(d.session.solved,3)]}}</p><h3>수집한 아이템</h3><ul><li v-for="item in [...d.session.items,...localItems]" :key="item">✧ {{item}}</li></ul><p v-if="!d.session.items.length&&!localItems.length">NPC 미션과 탐험으로 아이템을 모아요.</p><button @click="show(help)">조작법 다시 보기</button></aside></div><div class="dungeon-dialogue"><b>{{d.session.level===5?'코드 골렘':'안내 요정'}}</b><p>{{d.session.level===5?'네 번의 정확한 주문으로 골렘의 방어를 무너뜨리세요!':'금색 테두리 NPC를 찾아가세요. 가까이에서 E를 누르면 배움이 시작됩니다.'}}</p><small>WASD / 방향키 이동 · E 대화 · 코드 입력 중에는 이동하지 않아요.</small></div></section>
<section v-else-if="d.screen==='ending'" class="dungeon-panel dungeon-ending"><div class="graduation-badge" aria-label="Python 던전 탈출 수료 배지">✦<span>PYTHON<br/>DUNGEON<br/>CLEAR</span>✦</div><p>THE CODEX IS RESTORED</p><h2>파이썬의 서를 되찾았어요!</h2><p>{{hero.name}}와 함께 5개 지역의 미션 20개를 해결했습니다.</p><strong>이번 모험 +{{d.session.earned}}P · 최초 누적 {{d.archive.total}} / 200P</strong><p>코딩 도감과 오답 기록에서 배운 내용을 다시 살펴보세요.</p><div class="dungeon-toolbar"><button @click="openBook">코딩 도감 열기</button><button @click="askExit">모험 마치기</button></div></section>
<dialog ref="help" class="dungeon-modal" aria-label="던전 게임 방법" @cancel.prevent="close(help)"><h2>모험가의 첫 안내서</h2><ul><li>방향키 또는 WASD로 이동 · E 또는 스페이스로 NPC 대화</li><li>모바일: 왼쪽 방향 패드 이동 · 오른쪽 E 대화 버튼</li><li>NPC의 개념 설명 → 문제 해결 → 해설 읽기 순서로 진행해요.</li><li>미션 4개를 모두 풀면 다음 지역이 열립니다. 보스는 정답마다 HP 25 감소!</li><li>코드에서는 Python 기본 문법·리스트·문자열·함수를 사용할 수 있어요. import·파일·네트워크 접근은 지원하지 않아요.</li><li>코드 실행: 최대 2초·메모리 128MB·숨겨진 테스트 케이스 적용</li><li>종료·새로고침 시 진행 초기화 / 보상과 학습 기록은 영구 보관</li></ul><button @click="close(help)">알겠어요, 모험 시작!</button></dialog>
<dialog ref="npcDialog" class="dungeon-modal" aria-label="NPC 대화" @cancel.prevent="close(npcDialog)"><p>LEVEL {{d.session?.level}} / {{level.npcs[npc]}}</p><h2>{{level.concepts[npc]}}</h2><p>{{notes[(d.session?.level??1)-1][npc]}}</p><button v-if="npc===(d.session?.solved??0)&&d.session?.question" @click="openQuestion">{{d.session.level===5?'코드 주문으로 공격':'문제 풀기 →'}}</button><button v-else @click="close(npcDialog)">이미 배운 개념이에요 · 닫기</button></dialog>
<dialog ref="codeDialog" class="dungeon-modal dungeon-code-modal" aria-label="던전 코드 미션" @cancel.prevent="!d.busy&&close(codeDialog)"><template v-if="current"><div class="dungeon-modal-top"><small>{{{multiple:'4지선다',blank:'빈칸 채우기',output:'출력 결과 예측',fix:'코드 오류 수정',code:'직접 코드 작성'}[current.type]}} · LEVEL {{d.session?.level}}</small><button :disabled="d.busy" aria-label="미션 닫기" @click="close(codeDialog)">✕</button></div><h2>{{current.prompt}}</h2><pre v-if="!['fix','code'].includes(current.type)" class="dungeon-code"><code>{{current.code}}</code></pre><GameItemShop game="dungeon" :session-id="d.session?.id" :question-id="current?.id" :disabled="d.busy||!!feedback?.correct" @used="useGameItem"/><form @submit.prevent="submit"><fieldset :disabled="d.busy||feedback?.correct"><template v-if="current.type==='multiple'"><label v-for="option in current.options" :key="option.id" class="dungeon-option"><input v-model="draft" type="radio" :value="option.id" name="dungeon-answer" required/>{{option.label}}</label></template><label v-else-if="['fix','code'].includes(current.type)" class="dungeon-editor-label">Python 코드 에디터<textarea v-model="draft" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" maxlength="6000" rows="10" @keydown.tab.prevent="tab"/><small>{{draft.length}} / 6000자 · Tab 4칸 들여쓰기 · 서버 Python 테스트로 채점</small></label><label v-else class="dungeon-editor-label">답안<input v-model="draft" maxlength="200" required autocomplete="off" placeholder="답을 입력하세요"/></label></fieldset><button v-if="!feedback" class="dungeon-primary" :disabled="d.busy||!draft.trim()">{{d.busy?'격리 환경에서 채점 중…':'답안 제출'}}</button></form><div v-if="feedback" :class="['dungeon-feedback',{correct:feedback.correct}]" role="status"><template v-if="feedback.correct"><h3>{{d.session?.level===5?'⚔ 공격 성공!':'✓ 미션 해결!'}}</h3><p>{{feedback.explanation}}</p><pre class="dungeon-code"><code>{{feedback.solution}}</code></pre><strong v-if="feedback.reward" class="dungeon-point-gain">+{{feedback.reward}}P 획득!</strong><p v-else-if="feedback.levelCleared&&feedback.previouslyRewarded">이미 최초 보상을 받은 라운드입니다. 추가 포인트는 지급되지 않아요.</p><button @click="advance">{{feedback.levelCleared?d.session.done?'엔딩 보기 →':'다음 모험 지도 →':'해설 확인 · 모험 계속'}}</button></template><template v-else><h3>아직 봉인이 풀리지 않았어요.</h3><p v-if="feedback.execution">{{feedback.execution}}</p><p>힌트: {{feedback.hint}}</p><button @click="retry">힌트를 읽고 다시 풀기</button></template></div><p v-if="formError" role="alert">{{formError}}</p></template></dialog>
<dialog ref="exitDialog" class="dungeon-modal" aria-label="던전 게임 종료 확인" @cancel.prevent="cancelExit"><h2>모험을 종료할까요?</h2><p>게임을 종료하면 진행 상황이 초기화됩니다. 종료하시겠습니까?</p><p>획득 포인트·학습 기록·문제 풀이 이력은 유지됩니다.</p><div class="dungeon-toolbar"><button @click="cancelExit">계속하기</button><button @click="confirmExit">게임 종료</button></div></dialog>
<dialog ref="book" class="dungeon-modal dungeon-book" aria-label="Python 코딩 도감과 오답노트" @cancel.prevent="close(book)"><div class="dungeon-modal-top"><h2>Python 코딩 도감</h2><button aria-label="코딩 도감 닫기" @click="close(book)">✕</button></div><p>학습한 개념 {{d.archive.concepts.length}} / 20 · 최초 보상 {{d.archive.total}} / 200P <b v-if="d.archive.badge">✦ 던전 탈출 수료</b></p><div class="dungeon-toolbar"><button @click="bookTab='concepts'">수집한 개념</button><button @click="bookTab='attempts'">풀이·오답 기록</button></div><div v-if="bookTab==='concepts'" class="dungeon-concept-grid"><article v-for="concept in d.archive.concepts" :key="concept.concept_id"><small>LEVEL {{concept.level}}</small><h3>{{concept.title}}</h3><p>{{notes[concept.level-1][Number(concept.concept_id.split(':').at(-1))]}}</p></article><p v-if="!d.archive.concepts.length">NPC 미션을 풀면 이곳에 개념이 모여요.</p></div><template v-else><label class="dungeon-check"><input v-model="onlyWrong" type="checkbox"/>오답만 보기</label><p>최근 100회 기록 · 진행 중인 오답은 힌트만, 종료한 모험은 해설도 볼 수 있어요.</p><details v-for="attempt in attempts" :key="attempt.id"><summary>{{attempt.correct?'✓ 정답':'다시 복습'}} · LEVEL {{attempt.level}} · {{attempt.prompt}}</summary><pre class="dungeon-code">{{attempt.code}}</pre><p>내 답안</p><pre class="dungeon-code">{{attempt.answerLabel}}</pre><p>힌트: {{attempt.hint}}</p><p v-if="attempt.explanation">{{attempt.explanation}}</p><pre v-if="attempt.solution" class="dungeon-code">{{attempt.solution}}</pre></details><p v-if="!attempts.length">아직 해당 풀이 기록이 없어요.</p></template></dialog>
</div></template>
<style src="../dungeon.css"></style>
